(6966788, 1050422, 22459, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by snaffles:</b></div><hr/><i> I thought it meant beware, cows may be about to mate with sheep! </i></td></tr></table> <br/> <br/>Still laughing at this comment....thank you :)</td>', 'Originally posted by snaffles: I thought it meant beware, cows may be about to mate with sheep!   Still laughing at this comment....thank you :)', '2013-01-30 00:46:13.000000', NULL, 0),
(6966789, 1050432, 86218, '<td valign="top">Ek is sooooooo bly dit is jou foto die Amanda. Ek het gehoop dit is joune want die een kon net goed doen... Die bruin gras het my uitgeggooi maar dit kon eintlik net jy wees. Daar was nog een wat suid Afrikaans gelyk het en gewonder of dit dalk joune was maar ek was verkeerd. Baie geluk met jou Lint en jy kook deesade met die kamera...hoop nie Bees ly honger by die kookpotte nie.. ;)</td>', 'Ek is sooooooo bly dit is jou foto die Amanda. Ek het gehoop dit is joune want die een kon net goed doen... Die bruin gras het my uitgeggooi maar dit kon eintlik net jy wees. Daar was nog een wat suid Afrikaans gelyk het en gewonder of dit dalk joune was maar ek was verkeerd. Baie geluk met jou Lint en jy kook deesade met die kamera...hoop nie Bees ly honger by die kookpotte nie.. ;)', '2013-01-30 00:46:57.000000', NULL, 0),
(6966791, 1050315, 113156, '<td valign="top">WTG Rian, this was always going to do well, great idea.</td>', 'WTG Rian, this was always going to do well, great idea.', '2013-01-30 00:47:55.000000', NULL, 0),
