(6966797, 1050113, 66267, '<td valign="top">way way underrated</td>', 'way way underrated', '2013-01-30 00:55:18.000000', NULL, 0),
(6966804, 1050047, 86218, '<td valign="top">I knew that you would get more flack than credit for that border. I rated this image my highest...The only thing I would have changed this shot is too have the left border the same colour as the road sign red...and the rest of the border black. im thinking this would have created the impression that the road sign is actullly toppling through the frame strengthening the slippery theme. Just my thoughts and would be interesting to see this...maybe it would not look good not sure. Nice take on the challenge either way</td>', 'I knew that you would get more flack than credit for that border. I rated this image my highest...The only thing I would have changed this shot is too have the left border the same colour as the road sign red...and the rest of the border black. im thinking this would have created the impression that the road sign is actullly toppling through the frame strengthening the slippery theme. Just my thoughts and would be interesting to see this...maybe it would not look good not sure. Nice take on the challenge either way', '2013-01-30 01:14:49.000000', NULL, 0),
(6966807, 1050321, 128201, '<td valign="top">I knew you would rock it with this image! Nice work on the HM.</td>', 'I knew you would rock it with this image! Nice work on the HM.', '2013-01-30 01:19:57.000000', NULL, 0),
